//! Independent acceptance oracle — the agent is never pointed at this file.
use hex_cli::fmt::humanize_duration;

#[test] fn zero() { assert_eq!(humanize_duration(0), "0s"); }
#[test] fn bare_seconds() { assert_eq!(humanize_duration(45), "45s"); }
#[test] fn whole_minute() { assert_eq!(humanize_duration(60), "1m"); }
#[test] fn minute_seconds() { assert_eq!(humanize_duration(90), "1m 30s"); }
#[test] fn whole_hour() { assert_eq!(humanize_duration(3600), "1h"); }
#[test] fn hms() { assert_eq!(humanize_duration(3661), "1h 1m 1s"); }
#[test] fn whole_day() { assert_eq!(humanize_duration(86400), "1d"); }
#[test] fn dhms() { assert_eq!(humanize_duration(90061), "1d 1h 1m 1s"); }
